var apps by remember {
    mutableStateOf(mapOf({{apps.0.id}} to {{value.apps.docs}}, {{apps.1.id}} to {{value.apps.mail}}, {{apps.2.id}} to {{value.apps.calendar}}))
}
var savedApps by remember { mutableStateOf(apps) }
var sharing by remember { mutableStateOf({{value.dataSharing}}) }
var savedSharing by remember { mutableStateOf(sharing) }
var memory by remember { mutableStateOf({{value.memory}}) }
var savedMemory by remember { mutableStateOf(memory) }
var retention by remember { mutableStateOf({{value.retention}}) }
var savedRetention by remember { mutableStateOf(retention) }
var provider by remember { mutableStateOf({{value.provider}}) }
var savedProvider by remember { mutableStateOf(provider) }
val dirty = apps != savedApps || sharing != savedSharing || memory != savedMemory ||
    retention != savedRetention || provider != savedProvider

examples.setup:
var apps by remember {
    mutableStateOf(mapOf("docs" to true, "mail" to false, "calendar" to true))
}
var savedApps by remember { mutableStateOf(apps) }
var sharing by remember { mutableStateOf(false) }
var savedSharing by remember { mutableStateOf(sharing) }
var memory by remember { mutableStateOf(true) }
var savedMemory by remember { mutableStateOf(memory) }
var retention by remember { mutableStateOf("90d") }
var savedRetention by remember { mutableStateOf(retention) }
var provider by remember { mutableStateOf("") }
var savedProvider by remember { mutableStateOf(provider) }
val dirty = apps != savedApps || sharing != savedSharing || memory != savedMemory ||
    retention != savedRetention || provider != savedProvider

